toolScript:
let audioContext;
        let analyser;
        let microphone;
        let isMonitoring = false;
        let peakDb = 0;
        async function toggleMonitoring() {
            if (isMonitoring) {
                stopMonitoring();
            } else {
                await startMonitoring();
            }
        }
        async function startMonitoring() {
            try {
                const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
                audioContext = new (window.AudioContext || window.webkitAudioContext)();
                analyser = audioContext.createAnalyser();
                microphone = audioContext.createMediaStreamSource(stream);
                analyser.smoothingTimeConstant = 0.5;
                analyser.fftSize = 1024;
                microphone.connect(analyser);
                isMonitoring = true;
                document.getElementById('start-btn').innerHTML = '<span class="w-4 h-4 bg-red-500 rounded-sm"></span> HALT MONITORING';
                document.getElementById('status-text').innerText = "LIVE - ANALYSIS ACTIVE";
                document.getElementById('status-text').className = "text-sm text-emerald-400 font-mono uppercase tracking-widest";
                updateLoop();
            } catch (err) {
                // message box replacement
                const errorBox = document.createElement('div');
                errorBox.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-red-600 text-white px-8 py-4 rounded-2xl shadow-2xl z-[100] font-black uppercase text-xs tracking-widest animate-bounce";
                errorBox.innerText = "Microphone access is mandatory for decibel audit.";
                document.body.appendChild(errorBox);
                setTimeout(() => errorBox.remove(), 4000);
            }
        }
        function stopMonitoring() {
            isMonitoring = false;
            if (microphone) microphone.disconnect();
            document.getElementById('start-btn').innerHTML = '<span class="w-4 h-4 bg-yellow-400 rounded-full animate-pulse shadow-[0_0_10px_rgba(250,204,21,0.8)]"></span> INITIALIZE DOSIMETER';
            document.getElementById('status-text').innerText = "PAUSED";
            document.getElementById('status-text').className = "text-sm text-yellow-400 font-mono uppercase tracking-widest";
        }
        function updateLoop() {
            if (!isMonitoring) return;
            const array = new Uint8Array(analyser.frequencyBinCount);
            analyser.getByteFrequencyData(array);
            // Logic Strategy: Calculate RMS energy across specific human vulnerability spectrum
            let values = 0;
            for (let i = 0; i < array.length; i++) {
                values += array[i];
            }
            const average = values / array.length;
            // Logarithmic heuristic adjustment for standard MEMS microphones
            let db = Math.round(average * 0.82) + 28;
            if (db < 30) db = 30; // Ambient noise floor
            updateUI(db);
            requestAnimationFrame(updateLoop);
        }
        function updateUI(db) {
            const display = document.getElementById('db-display');
            const bar = document.getElementById('db-bar');
            display.innerText = db.toString().padStart(2, '0');
            bar.style.width = Math.min(100, (db / 120) * 100) + "%";
            // Peak Tracking Logic
            if (db > peakDb) {
                peakDb = db;
                document.getElementById('peak-val').innerText = peakDb + " dB";
            }
            // Hazard Categorization
            if (db >= 90) {
                display.className = "db-value text-red-500";
                bar.className = "h-full bg-red-600 shadow-[0_0_15px_rgba(239,68,68,0.5)]";
            } else if (db >= 80) {
                display.className = "db-value text-yellow-400";
                bar.className = "h-full bg-yellow-500";
            } else {
                display.className = "db-value text-emerald-400";
                bar.className = "h-full bg-emerald-500";
            }
            // NIOSH Exposure Logic: T = 8 / (2^((L-85)/3))
            if (db >= 85) {
                const hours = 8 / Math.pow(2, (db - 85) / 3);
                if (hours < 0.016) { // Threshold check for seconds
                    document.getElementById('time-limit').innerText = "< 1 Minute";
                    document.getElementById('time-limit').className = "text-4xl font-black text-red-600 tracking-tighter";
                } else if (hours < 1) {
                    document.getElementById('time-limit').innerText = Math.round(hours * 60) + " Minutes";
                    document.getElementById('time-limit').className = "text-4xl font-black text-orange-500 tracking-tighter";
                } else {
                    document.getElementById('time-limit').innerText = hours.toFixed(1) + " Hours";
                    document.getElementById('time-limit').className = "text-4xl font-black text-zinc-800 tracking-tighter";
                }
            } else {
                document.getElementById('time-limit').innerText = "Safe / 24+ Hrs";
                document.getElementById('time-limit').className = "text-4xl font-black text-emerald-600 tracking-tighter";
            }
        }
        // --- GLOBAL SCROLL LOGIC ---
